package main

import (
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

// Record definition
type EmpRec struct {
	ErId   string
	ErDept string
	ErHours decimal.Decimal
	ErRate  decimal.Decimal
}

// Working storage
var WsEofFlag string = "N"
var WsFirstFlag string = "Y"
var WsPrevDept string = "   "
var WsRegHours decimal.Decimal = decimal.NewFromInt(0)
var WsOtHours decimal.Decimal = decimal.NewFromInt(0)
var WsGross decimal.Decimal = decimal.NewFromInt(0)
var WsDeptTotal decimal.Decimal = decimal.NewFromInt(0)
var WsDeptCount int64 = 0
var WsGrandTotal decimal.Decimal = decimal.NewFromInt(0)
var WsGrandCount int64 = 0
var WsHoursEd string
var WsRateEd string
var WsGrossEd string
var WsDeptEd string
var WsGrandEd string

var CurrentEmp EmpRec

var inputLines []string
var inputIndex int

// helpers

func parseImpliedDecimal(s string, scale int32) decimal.Decimal {
	var b strings.Builder
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c >= '0' && c <= '9' {
			b.WriteByte(c)
		} else {
			b.WriteByte('0')
		}
	}
	digits := b.String()
	if digits == "" {
		digits = "0"
	}
	n := decimal.RequireFromString(digits)
	return n.Shift(-scale)
}

func storeDecimal(val decimal.Decimal, intDigits int, scale int32, rounded bool) decimal.Decimal {
	var q decimal.Decimal
	if rounded {
		q = val.Round(scale)
	} else {
		q = val.Truncate(scale)
	}
	totalDigits := intDigits + int(scale)
	shifted := q.Shift(scale)
	isNeg := shifted.IsNegative()
	absShifted := shifted.Abs()
	s := absShifted.StringFixed(0)
	if len(s) > totalDigits {
		s = s[len(s)-totalDigits:]
	}
	if scale == 0 {
		if s == "" {
			s = "0"
		}
		d, _ := decimal.NewFromString(s)
		if isNeg {
			d = d.Neg()
		}
		return d
	}
	if len(s) <= int(scale) {
		need := int(scale) + 1 - len(s)
		s = strings.Repeat("0", need) + s
	}
	intPartStr := s[:len(s)-int(scale)]
	fracPartStr := s[len(s)-int(scale):]
	if intPartStr == "" {
		intPartStr = "0"
	}
	decStr := intPartStr + "." + fracPartStr
	d, _ := decimal.NewFromString(decStr)
	if isNeg {
		d = d.Neg()
	}
	return d
}

func storeCount(val int64, digits int) int64 {
	mod := int64(1)
	for i := 0; i < digits; i++ {
		mod *= 10
	}
	if val >= mod || val < 0 {
		return val % mod
	}
	return val
}

func formatCount(cnt int64, width int) string {
	// zero padded
	// handle negative? not needed
	if cnt < 0 {
		cnt = -cnt
	}
	return fmt.Sprintf("%0*d", width, cnt)
}

func formatEdited(val decimal.Decimal, pic string) string {
	dotIdx := strings.Index(pic, ".")
	var intPic, fracPic string
	var fracCount int
	if dotIdx >= 0 {
		intPic = pic[:dotIdx]
		fracPic = pic[dotIdx+1:]
		for _, ch := range fracPic {
			if ch == 'Z' || ch == '9' {
				fracCount++
			}
		}
	} else {
		intPic = pic
		fracCount = 0
	}
	intDigitCount := 0
	for _, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			intDigitCount++
		}
	}
	vTrunc := val.Truncate(int32(fracCount))
	isNeg := vTrunc.IsNegative()
	shifted := vTrunc.Shift(int32(fracCount)).Abs()
	sShifted := shifted.StringFixed(0)
	var intStrRaw, fracStrRaw string
	if fracCount == 0 {
		intStrRaw = sShifted
		fracStrRaw = ""
	} else {
		if len(sShifted) <= fracCount {
			sShifted = strings.Repeat("0", fracCount+1-len(sShifted)) + sShifted
		}
		intStrRaw = sShifted[:len(sShifted)-fracCount]
		fracStrRaw = sShifted[len(sShifted)-fracCount:]
	}
	// prepare integer digits for picture
	var intDigitsForPic string
	if len(intStrRaw) > intDigitCount {
		intDigitsForPic = intStrRaw[len(intStrRaw)-intDigitCount:]
	} else {
		intDigitsForPic = strings.Repeat("0", intDigitCount-len(intStrRaw)) + intStrRaw
	}
	suppressionActive := true
	digitIdx := 0
	intFormatted := make([]rune, 0, len(intPic))
	for _, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			d := rune(intDigitsForPic[digitIdx])
			digitIdx++
			if ch == 'Z' {
				if d == '0' && suppressionActive {
					intFormatted = append(intFormatted, ' ')
				} else {
					intFormatted = append(intFormatted, d)
					suppressionActive = false
				}
			} else {
				intFormatted = append(intFormatted, d)
				suppressionActive = false
			}
		} else if ch == ',' {
			if suppressionActive {
				intFormatted = append(intFormatted, ' ')
			} else {
				intFormatted = append(intFormatted, ',')
			}
		} else {
			intFormatted = append(intFormatted, ch)
		}
	}
	var fracFormatted []rune
	if fracCount > 0 {
		fracIdx := 0
		for _, ch := range fracPic {
			if ch == 'Z' || ch == '9' {
				d := rune(fracStrRaw[fracIdx])
				fracIdx++
				fracFormatted = append(fracFormatted, d)
			} else {
				fracFormatted = append(fracFormatted, ch)
			}
		}
	}
	var result string
	if dotIdx >= 0 {
		result = string(intFormatted) + "." + string(fracFormatted)
	} else {
		result = string(intFormatted)
	}
	if isNeg {
		runes := []rune(result)
		for i, r := range runes {
			if r != ' ' && r != ',' && r != '.' {
				if i > 0 && runes[i-1] == ' ' {
					runes[i-1] = '-'
				} else {
					// fallback: replace first char
					if len(runes) > 0 {
						runes[0] = '-'
					}
				}
				result = string(runes)
				break
			}
		}
	}
	return result
}

func loadInputFile() {
	data, err := os.ReadFile("input.dat")
	if err != nil {
		inputLines = []string{}
		return
	}
	content := string(data)
	content = strings.ReplaceAll(content, "\r\n", "\n")
	content = strings.ReplaceAll(content, "\r", "\n")
	if content == "" {
		inputLines = []string{}
		return
	}
	rawLines := strings.Split(content, "\n")
	if strings.HasSuffix(content, "\n") {
		if len(rawLines) > 0 && rawLines[len(rawLines)-1] == "" {
			rawLines = rawLines[:len(rawLines)-1]
		}
	}
	inputLines = rawLines
}

// Paragraphs

func ReadPara() {
	if inputIndex >= len(inputLines) {
		WsEofFlag = "Y"
		return
	}
	line := inputLines[inputIndex]
	inputIndex++
	if len(line) < 17 {
		line = line + strings.Repeat(" ", 17-len(line))
	} else if len(line) > 17 {
		line = line[:17]
	}
	erId := line[0:5]
	erDept := line[5:8]
	erHoursRaw := line[8:12]
	erRateRaw := line[12:17]
	CurrentEmp.ErId = erId
	CurrentEmp.ErDept = erDept
	CurrentEmp.ErHours = parseImpliedDecimal(erHoursRaw, 1)
	CurrentEmp.ErRate = parseImpliedDecimal(erRateRaw, 2)
}

func ProcessPara() {
	if WsFirstFlag == "Y" {
		WsPrevDept = CurrentEmp.ErDept
		WsFirstFlag = "N"
	} else {
		if CurrentEmp.ErDept != WsPrevDept {
			DeptBreakPara()
			WsPrevDept = CurrentEmp.ErDept
		}
	}
	PayPara()
	ReadPara()
}

func PayPara() {
	forty := decimal.NewFromInt(40)
	if CurrentEmp.ErHours.GreaterThan(forty) {
		WsRegHours = storeDecimal(decimal.NewFromInt(40), 3, 1, false)
		diff := CurrentEmp.ErHours.Sub(forty)
		WsOtHours = storeDecimal(diff, 3, 1, false)
	} else {
		WsRegHours = storeDecimal(CurrentEmp.ErHours, 3, 1, false)
		WsOtHours = storeDecimal(decimal.NewFromInt(0), 3, 1, false)
	}
	onePointFive := decimal.RequireFromString("1.5")
	grossCalc := WsRegHours.Mul(CurrentEmp.ErRate).Add(WsOtHours.Mul(CurrentEmp.ErRate).Mul(onePointFive))
	WsGross = storeDecimal(grossCalc, 7, 2, true)
	newDeptTotal := WsDeptTotal.Add(WsGross)
	WsDeptTotal = storeDecimal(newDeptTotal, 9, 2, false)
	WsDeptCount = storeCount(WsDeptCount+1, 3)
	newGrandTotal := WsGrandTotal.Add(WsGross)
	WsGrandTotal = storeDecimal(newGrandTotal, 11, 2, false)
	WsGrandCount = storeCount(WsGrandCount+1, 5)
	WsHoursEd = formatEdited(CurrentEmp.ErHours, "ZZ9.9")
	WsRateEd = formatEdited(CurrentEmp.ErRate, "ZZ9.99")
	WsGrossEd = formatEdited(WsGross, "Z,ZZZ,ZZ9.99")
	line := CurrentEmp.ErId + " " + CurrentEmp.ErDept + " " + WsHoursEd + " " + WsRateEd + " " + WsGrossEd
	fmt.Println(line)
}

func DeptBreakPara() {
	WsDeptEd = formatEdited(WsDeptTotal, "ZZZ,ZZZ,ZZ9.99")
	countStr := formatCount(WsDeptCount, 3)
	line := "  DEPT " + WsPrevDept + " EMPLOYEES: " + countStr + " TOTAL: " + WsDeptEd
	fmt.Println(line)
	WsDeptTotal = decimal.NewFromInt(0)
	WsDeptCount = 0
}

func GrandPara() {
	WsGrandEd = formatEdited(WsGrandTotal, "ZZ,ZZZ,ZZZ,ZZ9.99")
	countStr := formatCount(WsGrandCount, 5)
	line := "GRAND TOTAL (" + countStr + "): " + WsGrandEd
	fmt.Println(line)
}

func MainPara() {
	loadInputFile()
	inputIndex = 0
	ReadPara()
	for WsEofFlag != "Y" {
		ProcessPara()
	}
	if WsFirstFlag != "Y" {
		DeptBreakPara()
	}
	GrandPara()
}

func main() {
	MainPara()
}
